import {createBatteryField} from './battery-field.js';
import {getLocale,setLocale} from './i18n.js';
const home=document.querySelector('#entry-screen'),app=document.querySelector('#app'),enter=document.querySelector('#enter-lab'),pause=document.querySelector('#entry-pause'),status=document.querySelector('#entry-status');
const skip=document.querySelector('#skip-content');
const reduced=matchMedia('(prefers-reduced-motion:reduce)');let field=null,paused=false,labPromise=null,token=0,busy=false;
const copy={zh:{title:['探索电池','的内部。'],description:'选择材料，展开结构，读懂实测数据。',enter:'进入实验室',loading:'正在进入…',hint:matchMedia('(pointer:coarse)').matches?'触摸画面，拨开电池。':'移动鼠标，拨开电池。',pause:'暂停动效',resume:'继续动效',static:'静态画面',error:'暂时无法打开实验室，请再试一次。',page:'Battery Lab · 电池的世界'},en:{title:['Inside','a battery.'],description:'Choose materials. Explore the structure. Read measured data.',enter:'Enter the lab',loading:'Opening the lab…',hint:matchMedia('(pointer:coarse)').matches?'Touch to move the cells.':'Move your pointer to part the cells.',pause:'Pause motion',resume:'Resume motion',static:'Still view',error:'The lab could not open. Please try again.',page:'Battery Lab · Inside a battery'}};
function localize(){const language=getLocale(),words=copy[language];skip.textContent=language==='en'?'Skip to main content':'跳到主内容';home.querySelectorAll('[data-home-text]').forEach(el=>el.textContent=words[el.dataset.homeText]);home.querySelectorAll('[data-home-title]').forEach((el,i)=>el.textContent=words.title[i]);enter.querySelector('span').textContent=words[busy?'loading':'enter'];pause.querySelector('span').textContent=words[reduced.matches||field?.static?'static':paused?'resume':'pause'];pause.setAttribute('aria-pressed',String(paused||reduced.matches));pause.disabled=reduced.matches||!!field?.static;home.querySelectorAll('[data-home-locale]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.homeLocale===language)));if(!home.hidden){document.documentElement.lang=language==='en'?'en':'zh-CN';document.title=words.page;}}
function mountField(){if(field)return;const old=home.querySelector('canvas'),fresh=old.cloneNode(false);old.replaceWith(fresh);field=createBatteryField(fresh,home);field.setPaused(paused);}
function writeRoute(route){if(location.hash!==route)history.pushState(null,'',route);}
function routeEvent(active){document.dispatchEvent(new CustomEvent('battery-lab-route',{detail:{active}}));}
function showHome(write=true){document.dispatchEvent(new CustomEvent('battery-lab-dismiss-modal'));skip.href='#entry-title';token++;busy=false;enter.disabled=false;enter.removeAttribute('aria-busy');home.classList.remove('is-leaving');app.hidden=true;app.inert=true;home.hidden=false;home.inert=false;if(write)writeRoute('#home');window.scrollTo({top:0,behavior:'instant'});routeEvent(false);mountField();field?.setExit(0);localize();if(labPromise)enter.focus({preventScroll:true});}
async function showLab(write=true,animate=true){const current=++token;busy=true;enter.disabled=true;enter.setAttribute('aria-busy','true');status.textContent='';localize();try{labPromise??=import('./app.js');await labPromise;}catch{labPromise=null;if(current!==token)return;busy=false;enter.disabled=false;enter.removeAttribute('aria-busy');status.textContent=copy[getLocale()].error;localize();return;}if(current!==token)return;
 if(animate&&!reduced.matches&&!home.hidden){home.classList.add('is-leaving');await new Promise(resolve=>{const start=performance.now();function exit(now){if(current!==token){resolve();return;}const progress=Math.min((now-start)/580,1);field?.setExit(progress*progress);if(progress<1)requestAnimationFrame(exit);else resolve();}requestAnimationFrame(exit);});}
 if(current!==token)return;document.dispatchEvent(new CustomEvent('battery-lab-dismiss-modal'));skip.href='#stage-title';field?.dispose();field=null;home.hidden=true;home.inert=true;home.classList.remove('is-leaving');app.hidden=false;app.inert=false;busy=false;enter.disabled=false;enter.removeAttribute('aria-busy');if(write)writeRoute('#lab');document.title=getLocale()==='en'?'Battery Lab · Battery assembly workbench':'Battery Lab · 电池组装实验室';window.scrollTo({top:0,behavior:'instant'});routeEvent(true);app.querySelector('#stage-title')?.focus({preventScroll:true});
 if(['#safety-section','#durability-section'].includes(location.hash)){app.querySelector('[data-step="3"]')?.click();document.querySelector(location.hash)?.scrollIntoView({behavior:reduced.matches?'instant':'smooth'});}
}
skip.addEventListener('click',event=>{event.preventDefault();const target=document.querySelector(home.hidden?'#stage-title':'#entry-title');target?.focus({preventScroll:true});target?.scrollIntoView({behavior:'instant',block:'start'});});
enter.addEventListener('click',()=>showLab());pause.addEventListener('click',()=>{paused=!paused;field?.setPaused(paused);localize();});home.querySelectorAll('[data-home-locale]').forEach(el=>el.addEventListener('click',()=>setLocale(el.dataset.homeLocale)));
document.addEventListener('languagechange',localize);reduced.addEventListener('change',localize);
document.addEventListener('click',event=>{const brand=event.target.closest('#app .brand');if(brand){event.preventDefault();showHome();}});
window.addEventListener('hashchange',()=>{if(!location.hash||location.hash==='#home')showHome(false);else if(app.hidden)showLab(false);});window.addEventListener('popstate',()=>{if(!location.hash||location.hash==='#home'){if(home.hidden||busy)showHome(false);}else if(app.hidden&&!busy)showLab(false);});
localize();if(location.hash&&location.hash!=='#home')showLab(false,false);else showHome(false);
